class Audited:
    def __init__(self, validator):
        self.validator = validator

    def __set_name__(self, owner, name):
        self.name = name
        self.slot = "_" + name            # storage key derived, not passed twice

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self                   # Model.amount → descriptor, for query DSL
        return getattr(obj, self.slot)

    def __set__(self, obj, value):        # presence of __set__ = data descriptor
        self.validator(self.name, value)  # validate BEFORE storing or logging
        old = getattr(obj, self.slot, None)   # first write → old is None
        setattr(obj, self.slot, value)        # per-INSTANCE storage
        obj.__dict__.setdefault("_audit", []).append((self.name, old, value))

def positive(name, v):
    if v <= 0:
        raise ValueError(f"{name} must be positive")

class Invoice:
    amount = Audited(positive)
    tax = Audited(positive)

Why it holds up: __set_name__ removes the duplicated-name footgun; all mutable state (value, audit log) lives on obj, so two invoices never share data — the classic descriptor bug is storing on self; obj is None branch makes Invoice.amount usable in expressions; validation precedes both storage and audit so the log never contains rejected values. Honest cost: each read/write is a Python call — in row-loop hot paths, fetch raw dicts and skip the model.

