# Дескриптор Audited: __set_name__, состояние на экземпляре, аудит в __set__
class Audited:
    def __init__(self, validator):
        self.validator = validator

    def __set_name__(self, owner, name):
        self.name = name
        self.slot = "_" + name            # ключ хранения вычислен, не передан дважды

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self                   # Model.amount → дескриптор, для query-DSL
        return getattr(obj, self.slot)

    def __set__(self, obj, value):        # наличие __set__ = data-дескриптор
        self.validator(self.name, value)  # валидация ДО сохранения и журнала
        old = getattr(obj, self.slot, None)   # первая запись → old это None
        setattr(obj, self.slot, value)        # хранение на ЭКЗЕМПЛЯРЕ
        obj.__dict__.setdefault("_audit", []).append((self.name, old, value))

def positive(name, v):
    if v <= 0:
        raise ValueError(f"{name} must be positive")

class Invoice:
    amount = Audited(positive)
    tax = Audited(positive)

Почему это работает: __set_name__ убирает грабли дублирования имени; всё изменяемое состояние (значение, журнал) живёт на obj, так что два инвойса не делят данные — классический баг дескриптора это хранение на self; ветка obj is None делает Invoice.amount пригодным в выражениях; валидация предшествует и сохранению, и аудиту, так что журнал не содержит отклонённых значений. Честная цена: каждое чтение/запись — Python-вызов; в горячих циклах по строкам берите сырые словари в обход модели.

