class C:
    @property                 # property defines __set__ → DATA descriptor
    def a(self):
        return "property"
    def b(self):              # a function → NON-data descriptor (only __get__)
        return "method"

c = C()
c.__dict__["a"] = "instance"   # smuggle into the instance dict
c.__dict__["b"] = lambda: "instance"

print(c.a)        # 1 — data descriptor vs instance dict
print(c.b())      # 2 — non-data descriptor vs instance dict

